package com.hmdp.ai.infrastructure.mcp;import com.hmdp.ai.domain.mcp.*;import org.springframework.stereotype.Component;import java.util.List;@Component public class McpToolDiscoveryService {private final McpClientFactory clients;public McpToolDiscoveryService(McpClientFactory clients){this.clients=clients;}public List<McpToolDescriptor>discover(McpServer server){clients.create().initialize(server);return clients.create().tools(server);}}
